// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller, address target) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(0));

        CallerHelper helper = new CallerHelper(c);

        vm.deal(address(helper), 1 ether);

        helper.doAirdrop();
        uint before = c.tokenBalance(address(helper));
        vm.assume(before > 0);

        bool ok;
        try helper.doAirdrop() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.tokenBalance(address(helper)) == before);
    }
}

contract CallerHelper {
    ModifierEntrancy immutable c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function doAirdrop() external {
        c.airDrop();
    }
}
